objects' "last modification time" do not exclude objects in a data sink.

=item * C<< $msg->transfer_options() >> / C<< $msg->transfer_options($value) >>

Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::TransferOptions>)

