=head2 Google::Storagetransfer::V1::TransferTypes::TransferCounters

A collection of counters that report the progress of a transfer operation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->objects_found_from_source() >> / C<< $msg->objects_found_from_source($value) >>

Type: C<Int64>

Objects found in the data source that are scheduled to be transferred,
excluding any that are filtered based on object conditions or skipped due
to sync.

=item * C<< $msg->bytes_found_from_source() >> / C<< $msg->bytes_found_from_source($value) >>

Type: C<Int64>

Bytes found in the data source that are scheduled to be transferred,
excluding any that are filtered based on object conditions or skipped due
to sync.

=item * C<< $msg->objects_found_only_from_sink() >> / C<< $msg->objects_found_only_from_sink($value) >>

Type: C<Int64>

Objects found only in the data sink that are scheduled to be deleted.

=item * C<< $msg->bytes_found_only_from_sink() >> / C<< $msg->bytes_found_only_from_sink($value) >>

Type: C<Int64>

Bytes found only in the data sink that are scheduled to be deleted.

=item * C<< $msg->objects_from_source_skipped_by_sync() >> / C<< $msg->objects_from_source_skipped_by_sync($value) >>

Type: C<Int64>

Objects in the data source that are not transferred because they already
exist in the data sink.

=item * C<< $msg->bytes_from_source_skipped_by_sync() >> / C<< $msg->bytes_from_source_skipped_by_sync($value) >>

Type: C<Int64>

Bytes in the data source that are not transferred because they already
exist in the data sink.

=item * C<< $msg->objects_copied_to_sink() >> / C<< $msg->objects_copied_to_sink($value) >>

Type: C<Int64>

Objects that are copied to the data sink.

=item * C<< $msg->bytes_copied_to_sink() >> / C<< $msg->bytes_copied_to_sink($value) >>

Type: C<Int64>

Bytes that are copied to the data sink.

=item * C<< $msg->objects_deleted_from_source() >> / C<< $msg->objects_deleted_from_source($value) >>

Type: C<Int64>

Objects that are deleted from the data source.

=item * C<< $msg->bytes_deleted_from_source() >> / C<< $msg->bytes_deleted_from_source($value) >>

Type: C<Int64>

Bytes that are deleted from the data source.

=item * C<< $msg->objects_deleted_from_sink() >> / C<< $msg->objects_deleted_from_sink($value) >>

Type: C<Int64>

Objects that are deleted from the data sink.

=item * C<< $msg->bytes_deleted_from_sink() >> / C<< $msg->bytes_deleted_from_sink($value) >>

Type: C<Int64>

Bytes that are deleted from the data sink.

=item * C<< $msg->objects_from_source_failed() >> / C<< $msg->objects_from_source_failed($value) >>

Type: C<Int64>

Objects in the data source that failed to be transferred or that failed
to be deleted after being transferred.

=item * C<< $msg->bytes_from_source_failed() >> / C<< $msg->bytes_from_source_failed($value) >>

Type: C<Int64>

Bytes in the data source that failed to be transferred or that failed to
be deleted after being transferred.

=item * C<< $msg->objects_failed_to_delete_from_sink() >> / C<< $msg->objects_failed_to_delete_from_sink($value) >>

Type: C<Int64>

Objects that failed to be deleted from the data sink.

=item * C<< $msg->bytes_failed_to_delete_from_sink() >> / C<< $msg->bytes_failed_to_delete_from_sink($value) >>

Type: C<Int64>

Bytes that failed to be deleted from the data sink.

=item * C<< $msg->directories_found_from_source() >> / C<< $msg->directories_found_from_source($value) >>

Type: C<Int64>

For transfers involving PosixFilesystem only.

Number of directories found while listing. For example, if the root
directory of the transfer is `base/` and there are two other directories,
`a/` and `b/` under this directory, the count after listing `base/`,
`base/a/` and `base/b/` is 3.

=item * C<< $msg->directories_failed_to_list_from_source() >> / C<< $msg->directories_failed_to_list_from_source($value) >>

Type: C<Int64>

For transfers involving PosixFilesystem only.

Number of listing failures for each directory found at the source.
Potential failures when listing a directory include permission failure or
block failure. If listing a directory fails, no files in the directory are
transferred.

=item * C<< $msg->directories_successfully_listed_from_source() >> / C<< $msg->directories_successfully_listed_from_source($value) >>

Type: C<Int64>

For transfers involving PosixFilesystem only.

Number of successful listings for each directory found at the source.

=item * C<< $msg->intermediate_objects_cleaned_up() >> / C<< $msg->intermediate_objects_cleaned_up($value) >>

Type: C<Int64>

Number of successfully cleaned up intermediate objects.

=item * C<< $msg->intermediate_objects_failed_cleaned_up() >> / C<< $msg->intermediate_objects_failed_cleaned_up($value) >>

Type: C<Int64>

Number of intermediate objects failed cleaned up.

=back

=head2 Google::Storagetransfer::V1::TransferTypes::NotificationConfig

Specification to configure notifications published to Pub/Sub.
Notifications are published to the customer-provided topic using the
following `PubsubMessage.attributes`:

* `"eventType"`: one of the
[EventType][google.storagetransfer.v1.NotificationConfig.EventType] values
* `"payloadFormat"`: one of the
[PayloadFormat][google.storagetransfer.v1.NotificationConfig.PayloadFormat]
values
* `"projectId"`: the
[project_id][google.storagetransfer.v1.TransferOperation.project_id] of the
`TransferOperation`
* `"transferJobName"`: the
[transfer_job_name][google.storagetransfer.v1.TransferOperation.transfer_job_name]
of the `TransferOperation`
* `"transferOperationName"`: the
[name][google.storagetransfer.v1.TransferOperation.name] of the
`TransferOperation`

The `PubsubMessage.data` contains a
[TransferOperation][google.storagetransfer.v1.TransferOperation] resource
formatted according to the specified `PayloadFormat`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->pubsub_topic() >> / C<< $msg->pubsub_topic($value) >>

Type: C<String>

Required. The `Topic.name` of the Pub/Sub topic to which to publish
notifications. Must be of the format: `projects/{project}/topics/{topic}`.
Not matching this format results in an
[INVALID_ARGUMENT][google.rpc.Code.INVALID_ARGUMENT] error.

=item * C<< $msg->event_types() >> / C<< $msg->event_types($value) >>

Type: C<Enum> (L<Google::Storagetransfer::V1::NotificationConfig::EventType>)

Event types for which a notification is desired. If empty, send
notifications for all event types.

=item * C<< $msg->payload_format() >> / C<< $msg->payload_format($value) >>

Type: C<Enum> (L<Google::Storagetransfer::V1::NotificationConfig::PayloadFormat>)

Required. The desired format of the notification message payloads.

=back

=head3 Enum: NotificationConfig::EventType

=over 4

=item * C<EVENT_TYPE_UNSPECIFIED> => C<0>

=item * C<TRANSFER_OPERATION_SUCCESS> => C<1>

=item * C<TRANSFER_OPERATION_FAILED> => C<2>

=item * C<TRANSFER_OPERATION_ABORTED> => C<3>

=back

=head3 Enum: NotificationConfig::PayloadFormat

=over 4

=item * C<PAYLOAD_FORMAT_UNSPECIFIED> => C<0>

=item * C<NONE> => C<1>

=item * C<JSON> => C<2>

=back

=head2 Google::Storagetransfer::V1::TransferTypes::LoggingConfig

Specifies the logging behavior for transfer operations.

Logs can be sent to Cloud Logging for all transfer types. See
[Read transfer
logs](https://cloud.google.com/storage-transfer/docs/read-transfer-logs) for
details.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->log_actions() >> / C<< $msg->log_actions($value) >>

Type: C<Enum> (L<Google::Storagetransfer::V1::LoggingConfig::LoggableAction>)

Specifies the actions to be logged. If empty, no logs are generated.

=item * C<< $msg->log_action_states() >> / C<< $msg->log_action_states($value) >>

Type: C<Enum> (L<Google::Storagetransfer::V1::LoggingConfig::LoggableActionState>)

States in which `log_actions` are logged. If empty, no logs are generated.

=item * C<< $msg->enable_onprem_gcs_transfer_logs() >> / C<< $msg->enable_onprem_gcs_transfer_logs($value) >>

Type: C<Bool>

For PosixFilesystem transfers, enables
[file system transfer
logs](https://cloud.google.com/storage-transfer/docs/on-prem-transfer-log-format)
instead of, or in addition to, Cloud Logging.

This option ignores [LoggableAction] and [LoggableActionState]. If these
are set, Cloud Logging will also be enabled for this transfer.

=back

