=over 4

=item * C<LOGGABLE_ACTION_UNSPECIFIED> => C<0>

=item * C<FIND> => C<1>

=item * C<DELETE> => C<2>

=item * C<COPY> => C<3>

=back

=head3 Enum: LoggingConfig::LoggableActionState

=over 4

=item * C<LOGGABLE_ACTION_STATE_UNSPECIFIED> => C<0>

=item * C<SUCCEEDED> => C<1>

=item * C<FAILED> => C<2>

=item * C<SKIPPED> => C<3>

=back

