Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::TransferSpec>)

Transfer specification.

=item * C<< $msg->notification_config() >> / C<< $msg->notification_config($value) >>

Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::NotificationConfig>)

Notification configuration.

=item * C<< $msg->logging_config() >> / C<< $msg->logging_config($value) >>

Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::LoggingConfig>)

