=item * C<< $msg->counters() >> / C<< $msg->counters($value) >>

Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::TransferCounters>)

Information about the progress of the transfer operation.

=item * C<< $msg->error_breakdowns() >> / C<< $msg->error_breakdowns($value) >>

Type: C<Message> (L<Google::Storagetransfer::V1::TransferTypes::ErrorSummary>)

Summarizes errors encountered with sample error log entries.

=item * C<< $msg->transfer_job_name() >> / C<< $msg->transfer_job_name($value) >>

Type: C<String>

The name of the transfer job that triggers this transfer operation.

=back

=head3 Enum: TransferOperation::Status

=over 4

=item * C<STATUS_UNSPECIFIED> => C<0>

=item * C<IN_PROGRESS> => C<1>

=item * C<PAUSED> => C<2>

=item * C<SUCCESS> => C<3>

=item * C<FAILED> => C<4>

=item * C<ABORTED> => C<5>

=item * C<QUEUED> => C<6>

=item * C<SUSPENDING> => C<7>

=back

